class Platforms:
    """The typed endpoint methods, one attribute per platform."""

    douyin: Douyin
    xiaohongshu: Xiaohongshu
    wechat_mp: WechatMp
    bilibili: Bilibili
    weibo: Weibo
    tiktok: Tiktok
    x: X
    youtube: Youtube

    def _init_platforms(self, client: OkData) -> None:
        self.douyin = Douyin(client)
        self.xiaohongshu = Xiaohongshu(client)
        self.wechat_mp = WechatMp(client)
        self.bilibili = Bilibili(client)
        self.weibo = Weibo(client)
        self.tiktok = Tiktok(client)
        self.x = X(client)
        self.youtube = Youtube(client)
